// Keyless convenience index — record JAH-GPC-SMARTLOCK-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"methods": 4, "battery_months": 12, "price_usd": 200};
var value = (m.methods*m.battery_months/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-SMARTLOCK-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-SMARTLOCK-000001|' + value.toFixed(2) + ' convenience index');

